// from the official standard : 
// " Each algorithm can be described in two stages: preprocessing and hash computation "

// "Preprocessing involves padding a message, parsing the padded message into m-bit blocks, and
// setting initialization values to be used in the hash computation. "


// "The hash computation generates
// a message schedule from the padded message and uses that schedule, along with functions,
// constants, and word operations to iteratively generate a series of hash values. The final hash
// value generated by the hash computation is used to determine the message digest"


static uint32_t bytes_to_be(uchar_t input[4]) {
    return (uint32_t) ((input[0] << 24) | (input[1] << 16) | (input[2] << 8) | input[3]) ;
}

// ????
static void be_to_bytes(uint32_t num , uchar_t input[4]) {
    input[0] = (num & 0xff000000 ) >> 24 ;
    input[1] = (num & 0x00ff0000 ) >> 16 ;
    input[2] = (num & 0x0000ff00 ) >> 8 ;
    input[3] = (num & 0x000000ff )  ;
}



static uint32_t rotl_32bit(uint32_t a , uint32_t times) {
    times %= 32 ;

    if (!times)
        return a ;


    return ((a << times) | (a >> (32 - times))) ;
}


static uint32_t rotr_32bit(uint32_t a , uint32_t times) {
    times %= 32 ;
    
    if (!times)
    return a ;
    
    
    return ((a >> times) | (a << (32 - times))) ;
}


static uint32_t shr_32bit(uint32_t a , uint32_t times) {
    return a >> times ;
}

static uint32_t shl_32bit(uint32_t a , uint32_t times) {
    return a << times ;
}


static void Ch_sha256(uchar_t *x , uchar_t *y , uchar_t *z , uchar_t *result) {

    uchar_t temp1[4] ;
    for (int i = 0; i < 4; i++)
    {
        temp1[i] = x[i] & y[i] ;
    }

    uchar_t temp2[4] ;
    for (int i = 0; i < 4; i++)
    {
        temp2[i] = (~x[i]) & z[i] ;
    }

    for (int i = 0; i < 4; i++)
    {
        result[i] = temp1[i] ^ temp2[i] ;
    }

}


static void Maj_sha256(uchar_t *x , uchar_t *y , uchar_t *z , uchar_t *result) {

    uchar_t temp1[4] ;
    for (int i = 0; i < 4; i++)
    {
        temp1[i] = x[i] & y[i] ;
    }

    uchar_t temp2[4] ;
    for (int i = 0; i < 4; i++)
    {
        temp2[i] = x[i] & z[i] ;
    }
    
    uchar_t temp3[4] ;

    for (int i = 0; i < 4; i++)
    {
        temp3[i] = y[i] & z[i] ;
    }


    for (int i = 0; i < 4; i++)
    {
        result[i] = temp1[i] ^ temp2[i] ^ temp3[i] ;
    }


}



static uint32_t Sum0_256_sha256(uint32_t num) {
    return rotr_32bit(num , 2) ^ rotr_32bit(num , 13) ^ rotr_32bit(num , 22)   ; 
}


static uint32_t Sum1_256_sha256(uint32_t num) {
    return rotr_32bit(num , 6) ^ rotr_32bit(num , 11) ^ rotr_32bit(num , 25)   ; 
}


static uint32_t Sigma0_256_sha256(uint32_t num) {
    return rotr_32bit(num , 7) ^ rotr_32bit(num , 18) ^ shr_32bit(num , 3)   ; 
}

static uint32_t Sigma1_256_sha256(uint32_t num) {
    return rotr_32bit(num , 17) ^ rotr_32bit(num , 19) ^ shr_32bit(num , 10)   ; 
}

