void sha256_hash(const uchar_t* data, size_t len, uchar_t digest[32]) {
    
    uchar_t H[8*4] ; 
    uchar_t W[64*4] ; 
    uchar_t K[64*4] ; 

    init_K(K) ;
    init_Hash_Values(H) ;


    uint64_t output_length  ; 
    uchar_t *input_padded = sha256_padding(data , 8*len , &output_length) ; 
    output_length /= 8 ; 

    uint32_t a , b , c , d , e ,f , g, h ;

    printf("N =  %d\n" , output_length) ; 
    printf("here you go looping from 0 to N/(16*4)-1 : %d\n" , output_length/(16*4)-1) ; 
    for (size_t i = 0; i <= output_length/(16*4)-1; i++)
    {

        // memcpy(X  , M + (i* 16 *4 ) , sizeof(uchar_t) * 4*16) ;
        for (size_t t = 0; t < 16; t++)
        {
            memcpy(W + (t*4) , input_padded + (t*4 ) , sizeof(uchar_t ) * 4 * 1) ; 
            // be_to_bytes(result , W + t*4 ) ;
        }
        for (size_t t = 16; t < 64; t++)
        {
            uint32_t result = Sigma1_256_sha256(bytes_to_be(W + (t -2)*4)) + bytes_to_be(W + (t -7)*4) + Sigma0_256_sha256(bytes_to_be(W + (t -15)*4)) + bytes_to_be(W + (t -16)*4)    ; 
            be_to_bytes(result , W + t*4 ) ;
        }
        
        a = bytes_to_be(H + 0*4) ; 
        b = bytes_to_be(H + 1*4) ; 
        c = bytes_to_be(H + 2*4) ; 
        d = bytes_to_be(H + 3*4) ; 
        e = bytes_to_be(H + 4*4) ; 
        f = bytes_to_be(H + 5*4) ; 
        g = bytes_to_be(H + 6*4) ; 
        h = bytes_to_be(H + 7*4) ; 
        
        
        
        for (size_t t = 0; t < 64; t++)
        {

            uchar_t a_bytes[4] ;
            uchar_t b_bytes[4] ;
            uchar_t c_bytes[4] ;
            uchar_t e_bytes[4] ;
            uchar_t f_bytes[4] ;
            uchar_t g_bytes[4] ;
            uchar_t result[4] ;
            be_to_bytes(e , e_bytes) ; 
            be_to_bytes(f , f_bytes) ; 
            be_to_bytes(g , g_bytes) ; 
            
            Ch_sha256(e_bytes , f_bytes , g_bytes , result) ;
            
            uint32_t T1 = h + Sum1_256_sha256(e) + bytes_to_be(result) + bytes_to_be(K + t*4) + bytes_to_be(W + t*4)   ;  
            
            be_to_bytes(a , a_bytes) ; 
            be_to_bytes(b , b_bytes) ; 
            be_to_bytes(c , c_bytes) ; 
            
            Maj_sha256(a_bytes , b_bytes , c_bytes , result) ; 
            uint32_t T2 =  Sum0_256_sha256(a) + bytes_to_be(result)    ;  
            
            h = g ;
            
            g = f ; 
            
            f = e ; 
            
            e = d + T1 ; 
            
            d = c ; 
            
            c = b ;
            
            b = a ; 
            
            a = T1 + T2 ;

        }

        be_to_bytes( a  +  bytes_to_be(H + 0*4)  ,H + 0*4 ) ; 
        be_to_bytes( b  +  bytes_to_be(H + 1*4)  ,H + 1*4 ) ; 
        be_to_bytes( c  +  bytes_to_be(H + 2*4)  ,H + 2*4 ) ; 
        be_to_bytes( d  +  bytes_to_be(H + 3*4)  ,H + 3*4 ) ; 
        be_to_bytes( e  +  bytes_to_be(H + 4*4)  ,H + 4*4 ) ; 
        be_to_bytes( f  +  bytes_to_be(H + 5*4)  ,H + 5*4 ) ; 
        be_to_bytes( g  +  bytes_to_be(H + 6*4)  ,H + 6*4 ) ; 
        be_to_bytes( h  +  bytes_to_be(H + 7*4)  ,H + 7*4 ) ; 
        

        // break;
    }

    memcpy(digest , H , sizeof(uchar_t)*8*4) ; 


}

